# Makes the SDR and HDR10 test clips the HDR spike scripts use (ffmpeg with libx264/libx265 and zimg), into .\clips.
$d = Join-Path $PSScriptRoot 'clips'; New-Item -ItemType Directory -Force $d | Out-Null
ffmpeg -hide_banner -loglevel error -y -f lavfi -i "testsrc2=size=1920x1080:rate=24:duration=20" -vf "format=yuv420p" -c:v libx264 -preset veryfast -crf 18 -color_primaries bt709 -color_trc bt709 -colorspace bt709 "$d\sdr-test.mkv"
# the same pattern in PQ / BT.2020 (SDR white at 203 nits), with a 0..10,000-nit ramp along the bottom
$fc = "[0]format=gbrpf32le,zscale=tin=709:pin=709:min=gbr:rin=full:t=linear:p=709:m=gbr:r=full:npl=203,zscale=tin=linear:pin=709:min=gbr:rin=full:t=smpte2084:p=2020:m=gbr:r=full:npl=203,zscale=tin=smpte2084:pin=2020:min=gbr:rin=full:t=smpte2084:p=2020:m=2020_ncl:r=tv,format=yuv420p10le[a];[1]format=gray,format=yuv420p10le[b];[a][b]overlay=0:920"
ffmpeg -hide_banner -loglevel error -y -f lavfi -i "testsrc2=size=1920x1080:rate=24:duration=20" -f lavfi -i "gradients=size=1920x160:c0=black:c1=white:x0=0:y0=0:x1=1920:y1=0:duration=20:rate=24" -filter_complex $fc -c:v libx265 -preset fast -crf 16 -pix_fmt yuv420p10le -x265-params "log-level=error:hdr10=1:colorprim=bt2020:transfer=smpte2084:colormatrix=bt2020nc:master-display=G(13250,34500)B(7500,3000)R(34000,16000)WP(15635,16450)L(10000000,1):max-cll=1000,400" -color_primaries bt2020 -color_trc smpte2084 -colorspace bt2020nc "$d\hdr-test.mkv"
